#include <iostream>
#include <memory>

class Resource {
public:
  Resource() { std::cout << "Resource acquired\n"; }
  ~Resource() { std::cout << "Resource released\n"; }
};

int main() {
  { // unique_ptr: exclusive ownership
    std::unique_ptr<Resource> resource1(new Resource);  // RAII in action, resource acquired
    // ... use resource1 ...
  } // unique_ptr goes out of scope, destructor called, resource released

  { // shared_ptr: shared ownership
    std::shared_ptr<Resource> resource2(new Resource);
    std::shared_ptr<Resource> resource3 = resource2; // shared ownership
    // ... use resource2 and resource3 ...
  } // Both shared_ptrs go out of scope, last one releases the resource

  return 0;
}
